// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading guaranteed to be ready before frame 0
const { fontFamily: interFamily } = loadInter();



export type TierListHookProps = Record<string, any>;

const TierListHook: React.FC<TierListHookProps> = ({
  backgroundColor = "#0A0A0A",
  transparentBackground = false,
  durationInSeconds = 6,
  accentColor = "#00E5C7",
  chipColorA = "#53DE72",
  chipColorB = "#DED453",
  chipColorC = "#E58A40",
  chipColorD = "#E55B5B",
  glassOpacity = 0.04,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Parser safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout Constants ---
  const rowW = 860 * s;
  const rowH = 200 * s;
  const gap = 24 * s;
  const cornerRadius = 28 * s;
  const totalH = 5 * rowH + 4 * gap;
  const stackStartY = (height - totalH) / 2;
  const stackStartX = (width - rowW) / 2;

  const cardW = 580 * s;
  const cardH = 800 * s;
  const fanCenterY = (height - cardH) / 2;
  const fanCenterX = (width - cardW) / 2;

  // --- Timing Constants ---
  const WHIP_STAGGER = Math.round(fps * 0.09); // ~90ms
  const MORPH_START = 60;
  const MORPH_DURATION = 35;
  const STAMP_BASE = MORPH_START + MORPH_DURATION + 10;
  const STAMP_STAGGER = Math.round(fps * 0.07); // ~70ms
  const TOP_ROW_START = STAMP_BASE + 4 * STAMP_STAGGER + 15;

  // --- Master Board Animations ---
  // The whole board scales down from 108% to 100% during the morph phase
  const boardScale = interpolate(
    frame,
    [MORPH_START, MORPH_START + MORPH_DURATION],
    [1.08, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  // --- Helpers ---
  const rowData = [
    { label: "?", color: accentColor },
    { label: "D", color: chipColorD },
    { label: "C", color: chipColorC },
    { label: "B", color: chipColorB },
    { label: "A", color: chipColorA },
  ];

  // Calculate SVG Rect Perimeter for Draw-on
  const rectPerimeter = 2 * rowW + 2 * rowH - 8 * cornerRadius + 2 * Math.PI * cornerRadius;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          transform: `scale(${boardScale})`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {rowData.map((item, i) => {
          // --- Per-Card Timing ---
          const whipStart = i * WHIP_STAGGER;
          
          // Phase 1: Whip In
          const whipProgress = spring({
            fps,
            frame: frame - whipStart,
            config: { damping: 14, stiffness: 80, mass: 0.8 },
            durationInFrames: 30,
          });

          // Overshoot to 1.03 during whip, then settle
          const whipScale = interpolate(
            whipProgress,
            [0, 0.7, 1],
            [0.5, 1.03, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Phase 2: Morph Progress
          const morphProgress = interpolate(
            frame,
            [MORPH_START, MORPH_START + MORPH_DURATION],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.exp) }
          );

          // Phase 2: Soft Blur Bloom during convergence
          // Peaks at 0.5 progress
          const bloomStrength = interpolate(
            morphProgress,
            [0, 0.5, 1],
            [0, 15, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.quad) }
          );

          // --- Spatial Math ---
          // State 0: Far right off-screen
          const startX = width + 600 * s;
          const startRot = 45;

          // State 1: Fanned out
          const fannedOffsetX = (i - 2) * 70 * s;
          const fannedOffsetY = Math.abs(i - 2) * 15 * s;
          const fanX = fanCenterX + fannedOffsetX;
          const fanY = fanCenterY + fannedOffsetY;
          const fanRot = (i - 2) * 10;

          // State 2: Stacked Rows
          const stackX = stackStartX;
          const stackY = stackStartY + i * (rowH + gap);
          const stackRot = 0;

          // Compute Current Geometry by blending states
          const currentX = interpolate(morphProgress, [0, 1], [
            interpolate(whipProgress, [0, 1], [startX, fanX]),
            stackX
          ]);
          
          const currentY = interpolate(morphProgress, [0, 1], [fanY, stackY]);
          
          const currentRot = interpolate(morphProgress, [0, 1], [
            interpolate(whipProgress, [0, 1], [startRot, fanRot]),
            stackRot
          ]);

          const currentW = interpolate(morphProgress, [0, 1], [cardW, rowW]);
          const currentH = interpolate(morphProgress, [0, 1], [cardH, rowH]);

          // Hide before whip starts to prevent any first-frame flash
          const isVisible = frame >= whipStart;

          // --- Phase 3 & 4: Stamps & Top Row Logic ---
          // Stamp order: A(4) -> B(3) -> C(2) -> D(1).  Top row (0) handles differently.
          const isLetterRow = i > 0;
          const stampStartFrame = STAMP_BASE + (4 - i) * STAMP_STAGGER;
          
          const stampScale = spring({
            fps,
            frame: frame - stampStartFrame,
            config: { damping: 12, stiffness: 150 },
          });

          // Single frame white flash shortly after stamp impacts
          const flashIntensity = interpolate(
            frame - stampStartFrame,
            [2, 3, 5],
            [0, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Top Row (i=0) specific animations
          const isTopRow = i === 0;
          const topRowDrawProgress = interpolate(
            frame,
            [TOP_ROW_START, TOP_ROW_START + 45],
            [rectPerimeter, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
          );
          
          const questionMarkScale = spring({
            fps,
            frame: frame - (TOP_ROW_START + 15),
            config: { damping: 14, stiffness: 100 },
          });

          // Continuous gentle pulse for the teal question mark
          const pulse = (Math.sin((frame - TOP_ROW_START) * 0.08) * 0.5 + 0.5) * 0.3;

          return (
            <div
              key={`card-${i}`}
              style={{
                position: "absolute",
                left: currentX,
                top: currentY,
                width: currentW,
                height: currentH,
                opacity: isVisible ? 1 : 0,
                transform: `rotate(${currentRot}deg) scale(${morphProgress < 1 ? whipScale : 1})`,
                transformOrigin: "center center",
                zIndex: 10 - i, // Top row is highest z-index
                backgroundColor: `rgba(255, 255, 255, ${glassOpacity})`,
                border: `1px solid rgba(255, 255, 255, 0.12)`,
                borderRadius: cornerRadius,
                boxShadow: "0 24px 48px -12px rgba(0,0,0,0.6)",
                backdropFilter: "blur(12px)",
                filter: `blur(${bloomStrength}px)`,
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-start",
                paddingLeft: 40 * s,
                transition: "none",
              }}
            >
              {/* Internal Contents (Chips) - Only visible when fully morphed into rows */}
              {morphProgress > 0.95 && isLetterRow && frame >= stampStartFrame && (
                <div
                  style={{
                    width: 120 * s,
                    height: 120 * s,
                    backgroundColor: "rgba(255, 255, 255, 0.06)",
                    borderRadius: 24 * s,
                    border: "1px solid rgba(255, 255, 255, 0.1)",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    transform: `scale(${interpolate(stampScale, [0, 1], [3, 1])})`,
                    opacity: interpolate(stampScale, [0, 0.5], [0, 1], { extrapolateRight: "clamp" }),
                    boxShadow: `0 0 30px ${item.color}20`,
                    transition: "none",
                  }}
                >
                  <span
                    style={{
                      color: item.color,
                      fontSize: 64 * s,
                      fontWeight: 800,
                      letterSpacing: "-0.04em",
                      textShadow: `0 0 20px ${item.color}60`,
                      transition: "none",
                    }}
                  >
                    {item.label}
                  </span>
                </div>
              )}

              {/* Top Row Special Content */}
              {morphProgress > 0.95 && isTopRow && (
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    transition: "none",
                  }}
                >
                  {/* Dashed Draw-on Border */}
                  <svg
                    width={currentW}
                    height={currentH}
                    style={{ position: "absolute", inset: 0, transition: "none" }}
                  >
                    <defs>
                      <mask id="draw-mask">
                        <rect
                          width={currentW}
                          height={currentH}
                          rx={cornerRadius}
                          fill="none"
                          stroke="white"
                          strokeWidth={4 * s}
                          strokeDasharray={rectPerimeter}
                          strokeDashoffset={topRowDrawProgress}
                          style={{ transition: "none" }}
                        />
                      </mask>
                    </defs>
                    <rect
                      width={currentW}
                      height={currentH}
                      rx={cornerRadius}
                      fill="none"
                      stroke={accentColor}
                      strokeWidth={3 * s}
                      strokeDasharray={`${12 * s} ${16 * s}`}
                      mask="url(#draw-mask)"
                      style={{ transition: "none" }}
                    />
                  </svg>

                  {/* Question Mark */}
                  {frame >= TOP_ROW_START + 15 && (
                    <span
                      style={{
                        color: accentColor,
                        fontSize: 96 * s,
                        fontWeight: 800,
                        transform: `scale(${questionMarkScale})`,
                        textShadow: `0 0 ${40 + pulse * 60}px ${accentColor}`,
                        opacity: 0.9 + pulse * 0.1,
                        transition: "none",
                      }}
                    >
                      {item.label}
                    </span>
                  )}
                </div>
              )}

              {/* White Impact Flash Overlay */}
              {isLetterRow && flashIntensity > 0 && (
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    backgroundColor: "white",
                    borderRadius: cornerRadius,
                    opacity: flashIntensity,
                    pointerEvents: "none",
                    mixBlendMode: "overlay",
                    transition: "none",
                  }}
                />
              )}
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default TierListHook;